95	/// Bundle of the run's permission/guard/redaction config, projected from
96	/// [`crate::RunContext`] into [`ToolContext`]. A struct (not a long positional
97	/// arg list) so same-typed fields like `default_guards`/`redact_output` can't be
98	/// transposed silently.
99	pub(crate) struct PermissionFields<Ctx>
100	where
101	    Ctx: Send + Sync + 'static,
102	{
103	    pub(crate) mode: PermissionMode,
104	    pub(crate) policy: Option<Arc<dyn PermissionPolicy<Ctx>>>,
105	    pub(crate) deny_rules: Vec<DenyRule>,
106	    pub(crate) allow_rules: Vec<AllowRule>,
107	    pub(crate) approval_handler: Option<Arc<dyn ApprovalHandler>>,
108	    pub(crate) guard_rules: Vec<crate::GuardRule>,
109	    pub(crate) default_guards: bool,
110	    pub(crate) redact_output: bool,
111	    pub(crate) extra_secrets: Vec<String>,
112	}
113	
114	/// Narrower view of [`crate::RunContext`] passed to [`Tool::invoke`].
115	///
116	/// Deliberately excludes the session handle: tools must not bypass the
117	/// runner's persistence by writing directly to the session log. The run-level
118	/// hook registry rides along as a `pub(crate)` carrier (used only by
119	/// `agent_as_tool` to fire `OnSubagentStop`); it is **not** exposed to `Tool`
120	/// impls — hooks fire *around* tool invocations, not from inside them.
121	pub struct ToolContext<Ctx>
122	where
123	    Ctx: Send + Sync + 'static,
124	{
125	    user_ctx: Arc<Ctx>,
126	    tracer: TracerHandle,
127	    cancel: CancellationToken,
128	    agent_depth: u32,
129	    max_agent_depth: u32,
130	    state: SessionState,
131	    actions: ActionsHandle,
132	    /// Carrier for the parent run's [`HookRegistry`], projected by
133	    /// [`crate::RunContext::to_tool_context`]. `pub(crate)` — read only by the
134	    /// `agent_as_tool` path to fire `OnSubagentStop`; not exposed to tools.
135	    pub(crate) hooks: HookRegistry<Ctx>,
136	    permission_mode: PermissionMode,
137	    // read by agent_as_tool in a later task
138	    pub(crate) permission_policy: Option<Arc<dyn PermissionPolicy<Ctx>>>,
139	    // read by agent_as_tool in a later task
140	    pub(crate) deny_rules: Vec<DenyRule>,
141	    /// Carrier: allow rules from the parent [`crate::RunContext`].
142	    pub(crate) allow_rules: Vec<AllowRule>,
143	    // read by agent_as_tool in a later task
144	    pub(crate) approval_handler: Option<Arc<dyn ApprovalHandler>>,
145	    /// Carrier: user guard rules from the parent [`crate::RunContext`].
146	    pub(crate) guard_rules: Vec<crate::GuardRule>,
147	    /// Carrier: whether built-in destructive guards are active.
148	    pub(crate) default_guards: bool,
149	    /// Carrier: whether tool-output redaction is active.
150	    pub(crate) redact_output: bool,
151	    /// Carrier: extra secret values to redact from tool output.
152	    pub(crate) extra_secrets: Vec<String>,
153	}
154	
155	impl<Ctx> ToolContext<Ctx>
156	where
157	    Ctx: Send + Sync + 'static,
158	{
159	    /// Construct a new [`ToolContext`].
160	    pub fn new(
161	        user_ctx: Arc<Ctx>,
162	        tracer: TracerHandle,
163	        cancel: CancellationToken,
164	        agent_depth: u32,
165	        max_agent_depth: u32,
166	    ) -> Self {
167	        Self {
168	            user_ctx,
169	            tracer,
170	            cancel,
171	            agent_depth,
172	            max_agent_depth,
173	            state: SessionState::new(),
174	            actions: ActionsHandle::new(),
175	            hooks: HookRegistry::new(),
176	            permission_mode: PermissionMode::Default,
177	            permission_policy: None,
178	            deny_rules: Vec::new(),
179	            allow_rules: Vec::new(),
180	            approval_handler: None,
181	            guard_rules: Vec::new(),
182	            default_guards: true,
183	            redact_output: true,
184	            extra_secrets: Vec::new(),
185	        }
186	    }
187	
188	    /// Borrow the user context.
189	    pub fn user_ctx(&self) -> &Arc<Ctx> {
190	        &self.user_ctx
191	    }
192	    /// Borrow the tracer handle.
193	    pub fn tracer(&self) -> &TracerHandle {
194	        &self.tracer
195	    }
196	    /// Borrow the cancellation token.
197	    pub fn cancel(&self) -> &CancellationToken {
198	        &self.cancel
199	    }
200	    /// Current agent-nesting depth (handoff + agent-as-tool). `AgentAsTool`
201	    /// reads this to bound recursion.
202	    pub fn agent_depth(&self) -> u32 {
203	        self.agent_depth
204	    }
205	    /// The configured maximum agent-nesting depth (from `RunConfig`, or the
206	    /// default when no runner installed a config).
207	    pub fn max_agent_depth(&self) -> u32 {
208	        self.max_agent_depth
209	    }
210	    /// Borrow the run-scoped [`SessionState`] shared across sub-agents.
211	    pub fn state(&self) -> &SessionState {
212	        &self.state
213	    }
214	    /// Borrow the [`ActionsHandle`]. A tool calls `ctx.actions().escalate()`
215	    /// to stop an enclosing [`crate::LoopAgent`].
216	    pub fn actions(&self) -> &ActionsHandle {
217	        &self.actions
218	    }
219	    /// Install the shared [`SessionState`] (used by
220	    /// [`crate::RunContext::to_tool_context`]).
221	    pub fn with_state(mut self, state: SessionState) -> Self {
222	        self.state = state;
223	        self
224	    }
225	    /// Install the [`ActionsHandle`] (used by
226	    /// [`crate::RunContext::to_tool_context`]).
227	    pub fn with_actions(mut self, actions: ActionsHandle) -> Self {
228	        self.actions = actions;
229	        self
230	    }
231	
232	    /// Install the run-level hook registry (used by
233	    /// [`crate::RunContext::to_tool_context`]). `pub(crate)` — read only by the
234	    /// `agent_as_tool` path to fire `OnSubagentStop`; not exposed to tools.
235	    pub(crate) fn with_hooks(mut self, hooks: HookRegistry<Ctx>) -> Self {
236	        self.hooks = hooks;
237	        self
238	    }
239	
240	    /// The run's permission mode. A tool may legitimately branch on this.
241	    pub fn permission_mode(&self) -> PermissionMode {
242	        self.permission_mode
243	    }
244	
245	    /// Install the permission/guard/redaction config (used by
246	    /// [`crate::RunContext::to_tool_context`]). The policy/deny/guard/handler
247	    /// fields are `pub(crate)` carriers read only by the `agent_as_tool` rebuild
248	    /// path — not exposed to tools.
249	    pub(crate) fn with_permissions(mut self, fields: PermissionFields<Ctx>) -> Self {
250	        self.permission_mode = fields.mode;
251	        self.permission_policy = fields.policy;
252	        self.deny_rules = fields.deny_rules;
253	        self.allow_rules = fields.allow_rules;
254	        self.approval_handler = fields.approval_handler;
255	        self.guard_rules = fields.guard_rules;
256	        self.default_guards = fields.default_guards;
257	        self.redact_output = fields.redact_output;
258	        self.extra_secrets = fields.extra_secrets;
259	        self
260	    }
261	
262	    /// The run's user guard rules (carrier for `agent_as_tool` rebuild).
263	    pub fn guard_rules(&self) -> &[crate::GuardRule] {
264	        &self.guard_rules
265	    }
266	}
