268	/// The result of a successful [`Tool::invoke`] call.
269	///
270	/// Field shape (multi-modal content, metadata) lands with later tickets.
271	/// Today `content` is the raw JSON value the tool returned.
272	#[derive(Debug, Clone, Default)]
273	#[non_exhaustive]
274	pub struct ToolOutput {
275	    /// The tool's return payload, as JSON.
276	    pub content: serde_json::Value,
277	}
278	
279	impl ToolOutput {
280	    /// Construct a [`ToolOutput`] with the given JSON content.
281	    pub fn new(content: serde_json::Value) -> Self {
282	        Self { content }
283	    }
284	}
