286	/// Errors raised by [`Tool::invoke`].
287	///
288	/// `InvalidArgs` is the single recoverable variant per ADR-10: the runner
289	/// is permitted to feed the schema errors back to the model once before
290	/// surfacing [`crate::AgentError::InvalidStructuredOutput`]. No other
291	/// variant is recoverable.
292	#[derive(Debug, thiserror::Error)]
293	#[non_exhaustive]
294	pub enum ToolError {
295	    /// Arguments did not match [`Tool::schema`].
296	    ///
297	    /// Recoverable per ADR-10 — the runner may feed `schema_errors` back to
298	    /// the model once before surfacing
299	    /// [`crate::AgentError::InvalidStructuredOutput`].
300	    #[error("invalid tool arguments: {schema_errors:?}")]
301	    InvalidArgs {
302	        /// Human-readable schema-validation errors.
303	        schema_errors: Vec<String>,
304	    },
305	
306	    /// The tool refused the operation: either a hard safety-boundary violation
307	    /// (a path outside the sandbox root, a non-UTF-8 read) or an unsatisfiable
308	    /// precondition (an ambiguous edit target, an allow/deny-blocked command).
309	    /// Distinct from a [`crate::PermissionPolicy`] denial, which the runner
310	    /// resolves before `invoke` is ever called. Not recoverable.
311	    #[error("operation denied: {reason}")]
312	    Denied {
313	        /// Human-readable denial reason, surfaced to the model.
314	        reason: String,
315	    },
316	
317	    /// Escape hatch for arbitrary tool failures. See ADR-10.
318	    #[error(transparent)]
319	    Other(#[from] anyhow::Error),
320	}
321	
322	/// Errors raised while resolving a [`ToolSource`] or merging resolved tools.
323	#[derive(Debug, thiserror::Error)]
324	#[non_exhaustive]
325	pub enum ToolSourceError {
326	    /// A source failed to produce its tools (e.g. a transport/discovery failure).
327	    ///
328	    /// Constructed by the failing [`ToolSource`] implementation, which supplies
329	    /// its own `source` label; the agent builder propagates it unchanged.
330	    #[error("tool source {source:?} failed to resolve: {cause}")]
331	    Resolution {
332	        /// Caller-meaningful label for the failing source (supplied by the impl).
333	        source: String,
334	        /// Underlying cause.
335	        #[source]
336	        cause: anyhow::Error,
337	    },
338	
339	    /// A resolved source introduced a tool whose name already exists in the
340	    /// merged namespace (static tools or an earlier source). Rejected at build
341	    /// time rather than silently shadowed, because tools dispatch by name.
342	    #[error("duplicate tool name {name:?} introduced by a tool source")]
343	    DuplicateName {
344	        /// The conflicting tool name.
345	        name: String,
346	    },
347	
348	    /// Escape hatch for arbitrary source failures.
349	    #[error(transparent)]
350	    Other(#[from] anyhow::Error),
351	}
352	
353	/// An asynchronous provider of [`Tool`]s, resolved when the agent is built.
354	///
355	/// Implemented by anything that can produce tools through (potentially) async
356	/// work — for example an MCP server handle that discovered its tools over a
357	/// transport. Register sources on the builder via its `tool_source`, `tool_sources`, or
358	/// `mcp_servers` methods; they are resolved exactly once by `build_resolved`.
359	///
360	/// Object-safe by the same construction as [`Tool`] — held as
361	/// `Arc<dyn ToolSource<Ctx>>`.
362	#[async_trait]
363	pub trait ToolSource<Ctx>: Send + Sync
364	where
365	    Ctx: Send + Sync + 'static,
366	{
367	    /// Resolve the tools this source provides.
368	    ///
369	    /// Called once, at `build_resolved()`. Returning `Err` aborts the build
370	    /// with that [`ToolSourceError`]. Implementations that want labeled errors
371	    /// construct [`ToolSourceError::Resolution`] themselves.
372	    async fn tools(&self) -> Result<Vec<Arc<dyn Tool<Ctx>>>, ToolSourceError>;
373	}
