1	//! `ToolDef` → Anthropic tool entries for the request body.
2	//!
3	//! Anthropic accepts permissive schemas — no strict-mode rewriting.
4	
5	use paigasus_helikon_core::ToolDef;
6	use serde_json::{json, Value};
7	
8	/// Translate the request's tool list into Anthropic's `tools:` array.
9	/// Cache markers are applied by `translate::cache`, not here.
10	pub(crate) fn translate_tools(defs: &[ToolDef]) -> Value {
11	    let arr: Vec<Value> = defs
12	        .iter()
13	        .map(|t| {
14	            json!({
15	                "name": t.name,
16	                "description": t.description,
17	                "input_schema": t.schema,
18	            })
19	        })
20	        .collect();
21	    Value::Array(arr)
22	}
23	
24	#[cfg(test)]
25	mod tests {
26	    use super::*;
27	
28	    #[test]
29	    fn translates_empty_list_to_empty_array() {
30	        assert_eq!(translate_tools(&[]), json!([]));
31	    }
32	
33	    #[test]
34	    fn passes_through_name_description_and_schema() {
35	        let defs = vec![ToolDef {
36	            name: "search".to_owned(),
37	            description: "search the web".to_owned(),
38	            schema: json!({"type": "object", "properties": {"q": {"type": "string"}}}),
39	        }];
40	        let out = translate_tools(&defs);
41	        assert_eq!(out[0]["name"], "search");
42	        assert_eq!(out[0]["description"], "search the web");
43	        assert_eq!(
44	            out[0]["input_schema"],
45	            json!({"type": "object", "properties": {"q": {"type": "string"}}}),
46	        );
47	    }
48	}
