1	//! `CacheStrategy` → cache_control marker placement.
2	//!
3	//! Anthropic accepts up to 4 cache breakpoints per request. Our placements
4	//! top out at 3 (system + tools + last turn).
5	
6	use serde_json::{json, Value};
7	
8	use crate::settings::CacheStrategy;
9	
10	/// Apply the cache strategy to the request body in-place.
11	///
12	/// `system` is normalized into block-array form when a system marker is
13	/// requested (Anthropic accepts a string OR an array; markers need the
14	/// array form). Returns the (possibly converted) system value.
15	pub(crate) fn apply_cache_strategy(
16	    strategy: CacheStrategy,
17	    system: Option<Value>,
18	    tools: &mut Value,
19	    messages: &mut Value,
20	) -> Option<Value> {
21	    let mark = || json!({"type": "ephemeral"});
22	    let system = match strategy {
23	        CacheStrategy::None => system,
24	        CacheStrategy::System | CacheStrategy::SystemAndTools => system.map(|s| {
25	            let mut blocks = match s {
26	                Value::String(text) => vec![json!({"type": "text", "text": text})],
27	                Value::Array(arr) => arr,
28	                _ => return s,
29	            };
30	            if let Some(last) = blocks.last_mut() {
31	                if let Some(obj) = last.as_object_mut() {
32	                    obj.insert("cache_control".to_owned(), mark());
33	                }
34	            }
35	            Value::Array(blocks)
36	        }),
37	        CacheStrategy::Tools | CacheStrategy::LastTurn => system,
38	    };
39	
40	    if matches!(
41	        strategy,
42	        CacheStrategy::Tools | CacheStrategy::SystemAndTools
43	    ) {
44	        if let Some(arr) = tools.as_array_mut() {
45	            if let Some(last) = arr.last_mut() {
46	                if let Some(obj) = last.as_object_mut() {
47	                    obj.insert("cache_control".to_owned(), mark());
48	                }
49	            }
50	        }
51	    }
52	
53	    if matches!(strategy, CacheStrategy::LastTurn) {
54	        if let Some(arr) = messages.as_array_mut() {
55	            if let Some(last_msg) = arr.last_mut() {
56	                if let Some(blocks) = last_msg["content"].as_array_mut() {
57	                    if let Some(last_block) = blocks.last_mut() {
58	                        if let Some(obj) = last_block.as_object_mut() {
59	                            obj.insert("cache_control".to_owned(), mark());
60	                        }
61	                    }
62	                }
63	            }
64	        }
65	    }
66	
67	    system
68	}
69	
