94	            name: SYNTHESIZED_TOOL_NAME.to_owned(),
95	            description: "x".to_owned(),
96	            schema: json!({}),
97	        }];
98	        let err = validate_tool_names(&defs).unwrap_err();
99	        assert!(err.contains("reserved"));
